mapper.select:
SELECT * FROM ads_platform_spread_timeline
WHERE event_id = #{eventId}
ORDER BY first_publish_time ASC

SELECT * FROM ads_platform_daily_heat
WHERE event_id = #{eventId}
ORDER BY time_bucket ASC, platform ASC


SELECT content_id, title, clean_text, source_url, platform, publish_time, category,
       hot_score, platform_heat_index, like_count, comment_count, repost_count, favorite_count
FROM ads_content_hot_rank

WHERE event_id = #{eventId}
  AND platform = #{platform}

  AND  = #{category}

  AND publish_time >= #{start}

  AND publish_time < #{end}

ORDER BY publish_time ASC, platform_heat_index DESC, id ASC

LIMIT #{offset}, #{limit}


SELECT COUNT(*)
FROM ads_content_hot_rank

WHERE event_id = #{eventId}
  AND platform = #{platform}

  AND  = #{category}

  AND publish_time >= #{start}

  AND publish_time < #{end}
